import { MakeLogicType, afterMount, connect, kea, key, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { platformAlertsEventsList } from 'products/alerts_platform/frontend/generated/api'
import { PlatformAlertEventApi } from 'products/alerts_platform/frontend/generated/api.schemas'

export interface TracesAlertEventHistoryLogicProps {
    alertId: string
}

// The API's cap, and more than a day of checks for an alert that changes state every few minutes.
const HISTORY_LIMIT = 100

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracesAlertEventHistoryLogicValues {
    currentTeamId: number | null // teamLogic
    events: PlatformAlertEventApi[]
    eventsLoadFailed: boolean
    eventsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracesAlertEventHistoryLogicActions {
    loadEvents: () => any
    loadEventsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadEventsSuccess: (
        events: PlatformAlertEventApi[],
        payload?: any
    ) => {
        events: PlatformAlertEventApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface tracesAlertEventHistoryLogicMeta {
    key: string
}

export type tracesAlertEventHistoryLogicType = MakeLogicType<
    tracesAlertEventHistoryLogicValues,
    tracesAlertEventHistoryLogicActions,
    TracesAlertEventHistoryLogicProps,
    tracesAlertEventHistoryLogicMeta
>

export const tracesAlertEventHistoryLogic = kea<tracesAlertEventHistoryLogicType>([
    path((key) => ['products', 'tracing', 'frontend', 'alerting', 'tracesAlertEventHistoryLogic', key]),
    props({} as TracesAlertEventHistoryLogicProps),
    key((props) => props.alertId),

    connect(() => ({
        values: [teamLogic, ['currentTeamId']],
    })),

    reducers({
        // A failed load leaves the list empty, which must not read as an alert with no history.
        eventsLoadFailed: [
            false,
            { loadEvents: () => false, loadEventsSuccess: () => false, loadEventsFailure: () => true },
        ],
    }),

    loaders(({ props, values }) => ({
        events: [
            [] as PlatformAlertEventApi[],
            {
                loadEvents: async () =>
                    await platformAlertsEventsList(String(values.currentTeamId), props.alertId, {
                        limit: HISTORY_LIMIT,
                    }),
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadEvents()
    }),
])
